			function setIpb2(){
			    var cmb1 = app.lookup("cmb1").value;
			    var cmb2 = app.lookup("cmb2").value;
			    var cmb3 = app.lookup("cmb3").value;
			    var ipb2 = app.lookup("ipb2"); 
			    if(cmb1 == "020399" || cmb2 == "020399" || cmb3 == "020399" ){
			        ipb2.enabled = true;
			    } else {
			        ipb2.value = "";
			        ipb2.enabled = false;
			    }
			}

			function valiChk(){
			    var dmHpeSrvc = app.lookup("dmHpeSrvc");
			    for(var i = 1; i <= 9; i++){
			        var cbgId = "cbg" + i;
			        var cbgValue = app.lookup(cbgId).value;
			        if(ValueUtil.isNull(cbgValue)){
			            var optResultCn = "optResultCn" + i;
			            util.Msg.alert(app, app.lookup(optResultCn).value + "을(를) 선택하세요.");
			            return false;
			        }
			    }
			    
			    for(var i = 1; i <= 3; i++){
			        var cmbId = "cmb" + i;
			        var cmbValue = app.lookup(cmbId).value;
			        if(ValueUtil.isNull(cmbValue)){
			            var cmbMsg = "개인적 목표 " + i + "순위를 선택하세요.";
			            util.Msg.alert(app, cmbMsg);
			            return false;
			        }
			    }
			    
			    if(app.lookup("ipb2").enabled){
			        if(ValueUtil.isNull(app.lookup("ipb2").value)){
			            util.Msg.alert(app, "개인적 목표 기타를 입력하세요.");
			            return false;
			        }
			    }

			    for(var i = 3; i <= 7; i++){
			        var ipbId = "ipb" + i;
			        if(app.lookup(ipbId).enabled){
			            var optResultCnSeq = i + 2;
			            var optResultCnId = "optResultCn" + optResultCnSeq;
			            var optResultCnValue = app.lookup(optResultCnId).value;
			            if(ValueUtil.isNull(app.lookup(ipbId).value)){
			                util.Msg.alert(app, optResultCnValue + "의 기타내용을 입력하세요.");
			                return false;
			            }
			        }
			    }
			    return true;
			}

