			function etcSet(cbgId){
			    var cbgVal = app.lookup(cbgId).value;
			    var ipbSeq = cbgId.replace("cbg", "") - 2;
			    var ipbId = "ipb" + ipbSeq;
			    if(cbgVal.indexOf("99") > -1){
			        app.lookup(ipbId).enabled = true;
			    } else {
			        app.lookup(ipbId).value  = "";
			        app.lookup(ipbId).enabled = false;
			    }
			    util.Control.redraw(app, "grpCont3");
			}

			function dataSet(){
			    var voInitValue = app.getHostProperty("initValue");
			    var dmHpeSrvc = app.lookup("dmHpeSrvc");
			    if(voInitValue.HPE_SRVC_RANKON_GOAL_SE_CD != null){
			        dmHpeSrvc.setValue("EXMN_YMD", voInitValue.EXMN_YMD);
			        dmHpeSrvc.setValue("HPE_SRVC_DIFFIC_SE_CD_NM", voInitValue.HPE_SRVC_DIFFIC_SE_CD_NM);
			        dmHpeSrvc.setValue("HPE_SRVC_DIFFIC_ETC_CN", voInitValue.HPE_SRVC_DIFFIC_ETC_CN);
			        dmHpeSrvc.setValue("HPE_SRVC_RANKON_GOAL_SE_CD", voInitValue.HPE_SRVC_RANKON_GOAL_SE_CD);
			        dmHpeSrvc.setValue("HPE_SRVC_RANKSE_GOAL_SE_CD", voInitValue.HPE_SRVC_RANKSE_GOAL_SE_CD);
			        dmHpeSrvc.setValue("HPE_SRVC_RANKTH_GOAL_SE_CD", voInitValue.HPE_SRVC_RANKTH_GOAL_SE_CD);
			        dmHpeSrvc.setValue("HPE_SRVC_GOAL_ETC_CN", voInitValue.HPE_SRVC_GOAL_ETC_CN);
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_SE_CD_NM", voInitValue.HPE_SRVC_DMD_SE_CD_NM);
			        var difficSeCdNm = dmHpeSrvc.getValue("HPE_SRVC_DIFFIC_SE_CD_NM").split(",");
			        //app.lookup("cbg1").selectItem(k);        
			        for(var i = 0; i < difficSeCdNm.length; i++){
			            for(var j = 1; j <= 4; j++){
			                var cbgId = "cbg" + j;
			                for(var k = 0; k < app.lookup(cbgId).getItemCount(); k++){
			                    var cbg = app.lookup(cbgId).getItem(k).value;
			                    if(difficSeCdNm[i] == cbg){
			                        app.lookup(cbgId).selectItem(k);
			                    }
			                }
			            }
			        }
			        
			        var dmdSeCdNm = dmHpeSrvc.getValue("HPE_SRVC_DMD_SE_CD_NM").split(",");
			        for(var i = 0; i < dmdSeCdNm.length; i++){
			            for(var j = 5; j <= 9; j++){
			                var cbgId = "cbg" + j;
			                for(var k = 0; k < app.lookup(cbgId).getItemCount(); k++){
			                    var cbg = app.lookup(cbgId).getItem(k).value;
			                    if(dmdSeCdNm[i] == cbg){
			                        app.lookup(cbgId).selectItem(k);
			                    }
			                }
			            }
			        }
			        
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_ETC_CN1", voInitValue.HPE_SRVC_DMD_ETC_CN1);
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_ETC_CN2", voInitValue.HPE_SRVC_DMD_ETC_CN2);
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_ETC_CN3", voInitValue.HPE_SRVC_DMD_ETC_CN3);
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_ETC_CN4", voInitValue.HPE_SRVC_DMD_ETC_CN4);
			        dmHpeSrvc.setValue("HPE_SRVC_DMD_ETC_CN5", voInitValue.HPE_SRVC_DMD_ETC_CN5);
			        
			        if(dmHpeSrvc.getValue("HPE_SRVC_RANKON_GOAL_SE_CD") != ""){
			            app.lookup("cmb2").enabled = true;
			            app.lookup("cmb3").enabled = true;
			        }
			        setIpb2();
			    }
			    if(voInitValue.MODY_YN != "Y"){
			        app.lookup("grpData").readOnly = true;
			        app.lookup("btn3").visible = false;
			    }
			    
			    util.Control.redraw(app, "grpData");
			//    console.log(dmHpeSrvc.getDatas());
			//    console.log(app.lookup("ipb3").value);
			//    console.log(app.lookup("ipb4").value);
			//    console.log(app.lookup("ipb5").value);
			//    console.log(app.lookup("ipb6").value);
			//    console.log(app.lookup("ipb7").value);
			}
